import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易闡真 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易闡真 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"classics/chanzhen/002.md","filePath":"classics/chanzhen/002.md"}'),s={name:"classics/chanzhen/002.md"};function n(c,p,i,o,l,h){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成，時乘六龍以御天。乾道變化，各正性命，保合太和，乃利貞。首出庶物，萬國咸寧。</p></blockquote><h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>初九：潛龍勿用。</p><p>九二：見龍在田，利見大人。</p><p>九三：君子終日乾乾，夕惕若，厲，無咎。</p><p>九四：或躍在淵，無咎。</p><p>九五：飛龍在天，利見大人。</p><p>上九：亢龍有悔。</p><p>用九：見群龍無首，吉。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：天行健，君子以自強不息。</p><p>乾為天，其德健。上乾天，下乾天，是天之一氣，上下流行不息，行健之象也。</p><p>君子有見於此，知人資天之氣而始，即有此天之健德，此德本來流行不息，無一時間斷，因交後天，棄真入假，健非所健，有時間斷矣。以是效天之行健，借假修真，於後天中返先天，自強不息焉。強者，剛強不屈，萬物難移之謂。若能自強，則正氣長存，內有主宰，富貴不能淫，貧賤不能移，威武不能屈，非禮不履，非道不處，非義不行，順之逆之，強而無處不在，強而無時或息，其行與天為徒矣。但世之強者有矣，強而為物所引，用之於外者有矣。或能自強，始勤終怠，遵道而行，半途而廢者亦有矣。自強實落功夫，全在不息，若稍有一點懈怠，稍有些子私慾，不得謂強，亦不得謂自強。惟不息之自強，方能造到渾然天理，堅剛不壞，永久長存地位。夫天者，命也。命者，健德，即本來一點浩然正氣。因其無影無形，活活潑潑，流行不息，謂之氣；因其至大至剛，充塞天地，謂之健；因其主宰萬有，為陰陽之祖，造化之根，謂之命。氣也，健也，命也，總一強也。一自強不息，而造命之功盡矣，此法天之學也。</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>乾者，健也，剛強不屈之義。卦體六爻皆奇，純陽之象，故謂乾。此進陽火之卦，造命之學，所以行健而用剛道也。健莫健於天，天之為道，一氣流行，循環無端，經久不已，無物不復，無物能傷，健之至矣。</p><p>故當春而生物者，健之元也。元者，初也，陽氣之初生。陽氣初生，而萬物俱皆萌甲，元何其健乎?</p><p>夏而長物者，健之亨也。亨者，通也，陽氣之通暢。陽氣通暢，而萬物俱皆發旺，亨何其健乎?</p><p>秋而成物者，健之利也。利者，宜也，陽氣之便宜。陽氣便宜，而萬物俱皆成實，利何其健乎?</p><p>冬而藏物者，健之貞也。貞者，靜也，陽氣之寧靜。陽氣寧靜，而萬物俱皆歸根，貞何其健乎?</p><p>元、亨、利、貞，四時迭運，總是一健行之，一為體而四為用。體以施用，用以全體，體用如一，故天道健行而不息也。</p><p>惟人也，資天之氣而始形，即具此天之健德，即有此元、亨、利、貞之健用。人之健德，即本來之良知、先天之正氣，名曰真陽，又曰真一之精，又曰真一之氣，儒曰精一，道曰抱一，釋曰歸一。無非教人修此一點剛健正氣耳。</p><p>是氣也，本於先天，藏於後天，處聖不增，處凡不減，有生之初，不垢亦不淨，不生亦不滅，不色亦不空，寂然不動，感而遂通，處於萬物之中，不為萬物所屈。本自元，本自亨，本自利，本自貞，皆在無心中運用，不待勉強，出於自然；不健而健，健而不健，健之無形跡可窺，所謂天人者是也。</p><p>一交後天，氣質發而外物誘，性相近而習相遠，棄真認假，良知有昧。於是元者不元，亨者不亨，利者不利，貞者不貞；健之德已虧，健之用已非，神昏氣濁，性亂命搖，身雖動而陽氣消，不死豈能之乎?</p><p>故聖人有造命之學，於後天中返先天，能以修持本來乾健之德，永久不壞耳。修持之道，仍不外此元、亨、利、貞之用。</p><p>人能看破一切，猛醒回頭，志於性命，恍惚杳冥之中，便有一點生機潛發，此健之元也。人能一心修養，真履實踐，經久不殆，行以達其所欲，即健之亨也。人能振發精神，勇力前進，剛氣凝聚，諸緣不礙，生死如一，即健之利也。人能格物致知，辨別是非邪正，止於其所而不遷，即健之貞也。</p><p>元以生其健，亨以通其健，利以成其健，貞以固其健。元、亨、利、貞一氣運用，由勉強而歸自然，渾然天理，仍是良知本來面目，可以與天同功用，與天同長久矣。</p><p>但是道也，有藥物，有火候，有功力，有急緩，有止足。修之合法，養之隨時，方能進於佳境。倘差之毫髮，失之千里。元、亨、利、貞，四者缺一，則健德不成，命非我有。此進陽之火候，不可不知也。</p><p>初九，在健之初，健德方振，如潛藏之龍，正當培養正氣之時，未可自恃其健，故曰“勿用”。</p><p>九二，健而得中，不偏不倚，剛柔相當，如見龍在田，生氣常存，天良不昧，聖胎有象。所謂大人者，不失其赤子之心者也，故曰“利見”。</p><p>九三，浩氣充塞，剛而得正，日則勉於行，夕則察其過，日乾夕惕，健行不息，雖有危厲，故能無咎。</p><p>九四，健德已成，聖胎完全，待時脫化，如龍或躍而起，或在於淵，審查氣候，防危慮險，故可無咎。</p><p>九五，剛健中正，陰陽混化，身外有身，形神俱妙，與道合真，不但成己，而且成物，如飛龍在天，隱顯不測，隨時濟物。所謂大人者，正己而正物者也，故曰“利見”。</p><p>上九，進健太過，獨剛不柔，知進而不知退，如亢旱之龍，龍至於亢，不能生物。健至太過，必敗其事。陽極必陰，天寶得而復失，理有可決，故曰“有悔”。</p><p>大抵行健用剛之道，貴乎隨時，隨時之健，能剛能柔，元、亨、利、貞，無往而不可健，無往而有傷健矣。</p><p>聖人恐人不知用健之道，大書特書曰：“用九，見群龍無首，吉。”此言太煞分明。九為河圖一三五，陽生之數。用九者，即用健也。龍之為靈昭昭也，變化不測，能上能下，能大能小，能隱能顯，迎之不見其首，隨之不見其後。修健之道，如御龍也。用健而能隨時，如群龍之變化也。當潛而潛，當見而見，當乾而乾，當躍而躍，當飛而飛，健而不至過，高而不至亢，緩急止足，各隨其時，此無首之健，用之而未有不取吉者。但無首變化之道，須要真知灼見。若不見而猜想做作，雖天寶在望，未許我得。用之必先見之，見而後用，則有用，用中無用，無功，功裡施功，有無不立，順逆不拘，大地裡黃芽長遍，滿世界金花開綻，信步走去，頭頭是道，取之左右逢其原，用九而不為九所用，方且進於剛健中正純粹之精，我命由我不由天，與天為徒矣。</p>',35)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
